"""GENERATED by scripts/make_canard_joints_fusion.py -- do not edit this file.

Wires (or verifies) the canard module's 8 hinge joints and drives the 4 revolute ones to
9.2 deg for a motion-check screenshot. Run the paired
out/reset_canard_joints_fusion_generated.py afterward to put the mechanism back at 0.
"""


import math

import adsk.core
import adsk.fusion


def _box(tbm, cx, cy, cz, lx, ly, lz):
    """An axis-aligned box in the GLOBAL X/Y/Z frame. mm in, cm internally."""
    obb = adsk.core.OrientedBoundingBox3D.create(
        adsk.core.Point3D.create(cx / 10.0, cy / 10.0, cz / 10.0),
        adsk.core.Vector3D.create(1.0, 0.0, 0.0),
        adsk.core.Vector3D.create(0.0, 1.0, 0.0),
        lx / 10.0, ly / 10.0, lz / 10.0)
    return tbm.createBox(obb)


def _cyl(tbm, x, y, z0, z1, r):
    """A cylinder on an axis PARALLEL TO Z, from z0 to z1. mm in, cm internally."""
    return tbm.createCylinderOrCone(
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z0 / 10.0), r / 10.0,
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z1 / 10.0), r / 10.0)


def _quadrant_axes(quadrant):
    """u = radial direction, v = tangential direction, at 90 deg * quadrant about Z."""
    a = math.radians(quadrant * 90.0)
    u = adsk.core.Vector3D.create(math.cos(a), math.sin(a), 0.0)
    v = adsk.core.Vector3D.create(-math.sin(a), math.cos(a), 0.0)
    return u, v


def _quadrant_box(tbm, quadrant, r_lo, r_hi, y_lo, y_hi, z_lo, z_hi):
    """A box whose length runs radially and width tangentially, at a given quadrant
    (0/1/2/3 = 0/90/180/270 deg about the rocket Z axis) -- ports
    `cad/canard_bay.fs`'s `quadrantCuboid`. mm in, cm internally.
    """
    u, v = _quadrant_axes(quadrant)
    r_lo, r_hi = min(r_lo, r_hi), max(r_lo, r_hi)
    y_lo, y_hi = min(y_lo, y_hi), max(y_lo, y_hi)
    z_lo, z_hi = min(z_lo, z_hi), max(z_lo, z_hi)
    rc, yc, zc = (r_lo + r_hi) / 2.0, (y_lo + y_hi) / 2.0, (z_lo + z_hi) / 2.0
    center = adsk.core.Point3D.create(
        (u.x * rc + v.x * yc) / 10.0, (u.y * rc + v.y * yc) / 10.0, zc / 10.0)
    obb = adsk.core.OrientedBoundingBox3D.create(
        center, u, v, (r_hi - r_lo) / 10.0, (y_hi - y_lo) / 10.0, (z_hi - z_lo) / 10.0)
    return tbm.createBox(obb)


def _radial_cyl(tbm, quadrant, across, z, r0, r1, r):
    """A cylinder on a RADIAL axis at the given quadrant, spanning radius r0 -> r1, offset
    `across` tangentially -- ports `cad/canard_bay.fs`'s `radialCylinder`. mm in, cm
    internally.
    """
    u, v = _quadrant_axes(quadrant)
    bx, by = v.x * across, v.y * across
    p0 = adsk.core.Point3D.create((bx + u.x * r0) / 10.0, (by + u.y * r0) / 10.0, z / 10.0)
    p1 = adsk.core.Point3D.create((bx + u.x * r1) / 10.0, (by + u.y * r1) / 10.0, z / 10.0)
    return tbm.createCylinderOrCone(p0, r / 10.0, p1, r / 10.0)


def _cut(tbm, target, tool, what):
    """Boolean subtract. NOTE: booleanOperation returns a BOOL and mutates `target` in
    place -- never assign its result back, per make_sled_fusion.py's own warning.
    """
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.DifferenceBooleanType):
        raise ValueError("cut %s did not take" % what)


def _union(tbm, target, tool, what):
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.UnionBooleanType):
        raise ValueError("union %s did not take" % what)


def _get_or_create_component(root, name):
    """Find an existing occurrence by component name, else create a new empty one.

    Returns (occurrence, already_has_bodies). A caller that finds `already_has_bodies`
    True should verify rather than rebuild -- the same idempotency rule
    `make_sled_fusion.py` uses.
    """
    for o in root.occurrences:
        if o.component.name == name:
            return o, o.component.bRepBodies.count > 0
    occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
    occ.component.name = name
    return occ, False


def _inject(comp, made):
    """Inject a list of (name, body) temporary BRep bodies through one BaseFeature.

    Mandatory for a parametric document: a temp body only "takes" via
    `BRepBodies.add(body, baseFeature)`, per make_sled_fusion.py's own header.

    RENAMING HAPPENS AFTER `finishEdit()`, VIA A FRESH QUERY -- not on the object
    `BRepBodies.add()` itself returns, and not inside the startEdit/finishEdit
    transaction. Confirmed by direct test: for a body sourced from Fusion's parametric
    Sketch/Extrude API (copied out via `TemporaryBRepManager.copy()`, the technique the
    canard panels and aft fins both use for their swept-trapezoid profile), setting
    `.name` on the object `.add()` returns reads back correctly on THAT SAME object but
    does not persist to the body at all -- a fresh `comp.bRepBodies` query even in the
    same script run still shows Fusion's own default name ("Body1"). Renaming a FRESH
    query result AFTER `finishEdit()` does persist, for both extrude-sourced and
    primitive-sourced (box/cylinder/boolean) bodies alike, so every generator does it
    this way now rather than the two of them disagreeing on which pattern is safe. This
    is a DIFFERENT failure mode from `_get_or_create_component`'s own idempotency note
    above (same-transaction rename into an ALREADY-POPULATED component) -- that one is
    about a LATER, separate script run; this one bites inside the very run that created
    the body.
    """
    before = comp.bRepBodies.count
    bf = comp.features.baseFeatures.add()
    bf.startEdit()
    for (name, body) in made:
        comp.bRepBodies.add(body, bf)
    bf.finishEdit()
    for i, (name, _body) in enumerate(made):
        comp.bRepBodies.item(before + i).name = name


def _verify_volume(comp, want, tol, loose=(), loose_tol=None):
    """Compare each named body's volume (mm3) against an analytic expectation.

    `loose` names bodies (radial holes through curved walls, or a part whose analytic
    figure is itself an estimate) that get `loose_tol` instead of `tol` -- measured, not
    guessed, the same discipline make_sled_fusion.py's PORT_VOLUME_TOLERANCE_PER_PORT uses.
    Returns a list of violation strings (empty if everything is within tolerance).
    """
    acc = adsk.fusion.CalculationAccuracy.VeryHighCalculationAccuracy
    got = {}
    for b in comp.bRepBodies:
        got[b.name] = b.getPhysicalProperties(acc).volume * 1e3
    bad = []
    for name, wv in want.items():
        if name not in got:
            bad.append("%s is missing" % name)
            continue
        t = loose_tol if (name in loose and loose_tol is not None) else tol
        d = got[name] - wv
        print("  %-28s %14.4f mm3  want %14.4f  delta %+9.4f  (tol %.3f)"
              % (name, got[name], wv, d, t))
        if abs(d) > t:
            bad.append("%s is %+.4f mm3 out" % (name, d))
    return bad


def _verify_cyl_faces(body, radius, axis_is_radial):
    """Count cylindrical faces at `radius` (mm) and read back their clocking, in degrees
    mod 180. `axis_is_radial` True keeps only faces whose axis has no Z component (a
    radial hole); False keeps only faces whose axis IS parallel to Z (an axial hole).
    Exact where a volume check on a radial hole through a curved wall is not -- see
    make_sled_fusion.py's header for why that matters.
    """
    found = []
    for f in body.faces:
        g = f.geometry
        if not g.objectType.endswith("Cylinder"):
            continue
        if abs(g.radius * 10.0 - radius) > 1e-6:
            continue
        ax = g.axis
        is_radial = abs(ax.z) < 1e-9
        if is_radial != axis_is_radial:
            continue
        found.append(math.degrees(math.atan2(ax.y, ax.x)) % 180.0)
    return sorted(found)


DRIVE_ANGLE_DEG = 9.2


def _occ(root, name):
    for o in root.occurrences:
        if o.component.name == name:
            return o
    raise ValueError("no occurrence named %r" % name)


def _largest_cyl_face(body):
    """The hinge axis face -- LARGEST area, not just the first cylindrical face found.
    A stepped shaft has more than one cylinder (the rod's own OD, and the narrower,
    shorter spline socket bore); picking the wrong one silently hinges on the wrong axis.
    """
    faces = [f for f in body.faces if f.geometry.objectType.endswith("Cylinder")]
    if not faces:
        raise ValueError("no cylindrical face on body %r" % body.name)
    return max(faces, key=lambda f: f.area)


def _find_joint(root, name_a, name_b, motion_cls):
    """Find an existing AsBuiltJoint between the occurrences named `name_a`/`name_b`
    (either order) carrying a `motion_cls` JointMotion -- by inspecting live state, not
    by trusting a name this generator set itself. See the module docstring for why.
    """
    for j in root.asBuiltJoints:
        names = {j.occurrenceOne.component.name, j.occurrenceTwo.component.name}
        if names == {name_a, name_b} and motion_cls.cast(j.jointMotion) is not None:
            return j
    return None


def run(_context: str):
    app = adsk.core.Application.get()
    des = adsk.fusion.Design.cast(app.activeProduct)
    root = des.rootComponent

    tube_occ = _occ(root, "Tube")

    made_rigid = 0
    made_revolute = 0
    joints = []

    for q in range(4):
        shaft_name = "Shaft%d" % q
        panel_name = "Panel%d" % q
        shaft_occ = _occ(root, shaft_name)
        panel_occ = _occ(root, panel_name)

        rigid = _find_joint(root, shaft_name, panel_name, adsk.fusion.RigidJointMotion)
        if rigid is None:
            inp = root.asBuiltJoints.createInput(shaft_occ, panel_occ, None)
            inp.setAsRigidJointMotion()
            rigid = root.asBuiltJoints.add(inp)
            if rigid is None:
                raise ValueError("q%d rigid joint (shaft-panel) failed to create" % q)
            made_rigid += 1

        revolute = _find_joint(root, shaft_name, "Tube", adsk.fusion.RevoluteJointMotion)
        if revolute is None:
            shaft_body = shaft_occ.bRepBodies.item(0)
            face = _largest_cyl_face(shaft_body)
            geo = adsk.fusion.JointGeometry.createByCylinderOrConeFace(
                face, adsk.fusion.JointQuadrantAngleTypes.StartJointQuadrantAngleType,
                adsk.fusion.JointKeyPointTypes.MiddleKeyPoint)
            inp = root.asBuiltJoints.createInput(shaft_occ, tube_occ, geo)
            inp.setAsRevoluteJointMotion(adsk.fusion.JointDirections.ZAxisJointDirection)
            revolute = root.asBuiltJoints.add(inp)
            if revolute is None:
                raise ValueError("q%d revolute joint (shaft-tube) failed to create" % q)
            made_revolute += 1

        joints.append((q, rigid, revolute))

    print("joints: %d new rigid, %d new revolute (8 total expected across all quadrants)"
          % (made_rigid, made_revolute))

    bad = []
    for (q, rigid, revolute) in joints:
        if adsk.fusion.RigidJointMotion.cast(rigid.jointMotion) is None:
            bad.append("q%d rigid joint is not RigidJointMotion" % q)
        if adsk.fusion.RevoluteJointMotion.cast(revolute.jointMotion) is None:
            bad.append("q%d revolute joint is not RevoluteJointMotion" % q)
    if bad:
        raise ValueError("VERIFY FAILED: " + "; ".join(bad))
    print("  OK -- 8 joints present, correctly typed (4 rigid shaft-panel, "
          "4 revolute shaft-tube)")

    # ---- motion check: drive all 4 revolute joints, screenshot from outside this
    # script, reset in a SEPARATE follow-up script -- "a joint that added successfully
    # and one that turns are different claims" (docs/01-next-steps.md correction 43) ----
    for (q, rigid, revolute) in joints:
        rvm = adsk.fusion.RevoluteJointMotion.cast(revolute.jointMotion)
        rvm.rotationValue = math.radians(DRIVE_ANGLE_DEG)
        readback = math.degrees(rvm.rotationValue)
        print("  q%d revolute driven to %.4f deg" % (q, readback))
        if abs(readback - DRIVE_ANGLE_DEG) > 1e-6:
            raise ValueError("q%d revolute did not reach %.1f deg, read back %.4f"
                             % (q, DRIVE_ANGLE_DEG, readback))
    print("  all 4 revolute joints driven to %.1f deg -- screenshot before resetting"
          % DRIVE_ANGLE_DEG)
